mapper.select:
select id, order_no, volunteer_id, execute_images, execute_video, remark,
       status, audit_status, audit_time, service_hours, create_time, update_time
from task_execute
where volunteer_id = #{volunteerId}

    and status = #{status}

order by create_time desc
limit #{offset}, #{limit}

mapper.update:
update task_execute
execute_images = #{executeImages}, execute_video = #{executeVideo}, remark = #{remark}, status = #{status}, audit_status = #{auditStatus}, audit_time = #{auditTime}, service_hours = #{serviceHours}, update_time = sysdate(),
where id = #{id}

mapper.select:
select count(1) from task_execute te
inner join order_protect op on te.order_no = op.order_no
where op.org_id = #{orgId}

    and DATE(te.create_time) >= #{startDate}


    and DATE(te.create_time) <= #{endDate}

select count(1) from task_execute te
inner join order_protect op on te.order_no = op.order_no
where op.org_id = #{orgId} and te.audit_status = 1

    and DATE(te.create_time) >= #{startDate}


    and DATE(te.create_time) <= #{endDate}
